<?php
namespace App\Jobs;
use App\Jobs\Concerns\HasTenantContext; use App\Models\TenantExport; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Bus\Queueable; use Illuminate\Support\Facades\Storage;
final class ExportTenantData implements ShouldQueue { use Queueable,HasTenantContext; public function __construct(string $tenantId,public readonly string $exportId){$this->tenantId=$tenantId;} public function handle():void{$export=TenantExport::where('tenant_id',$this->tenantId)->findOrFail($this->exportId);try{$payload=['tenant_id'=>$this->tenantId,'exported_at'=>now()->toIso8601String(),'note'=>'Data export manifest; sensitive files require separate approved export adapters.'];$path='private/tenant-exports/'.$export->id.'.json';Storage::disk('local')->put($path,json_encode($payload,JSON_THROW_ON_ERROR));$export->update(['state'=>'completed','private_path'=>$path,'completed_at'=>now()]);}catch(\Throwable $e){$export->update(['state'=>'failed','error'=>$e->getMessage()]);throw $e;}} }
